package com.rapidresolve;
import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
@WebServlet("/deleteProblem") public class DeleteProblemServlet extends HttpServlet { protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{HttpSession h=r.getSession(false);if(h==null||h.getAttribute("userId")==null){s.sendRedirect("login.html");return;}try(Connection c=DBConnection.getConnection();PreparedStatement q=c.prepareStatement("DELETE FROM problems WHERE id=? AND user_id=?")){q.setInt(1,Integer.parseInt(r.getParameter("id")));q.setInt(2,(Integer)h.getAttribute("userId"));q.executeUpdate();s.sendRedirect("view-problems");}catch(Exception e){s.sendRedirect("view-problems?error=delete");}}}
